#include <set>
#include <algorithm>
#include <iostream>

void search_demo(const std::set<int>& s, int key) {
    // O(log N) - Preferred method
    if (s.find(key) != s.end()) {
        std::cout << "Found via member find (Logarithmic)\n";
    }

    // O(N) - Avoid, unless searching based on a custom predicate
    auto it = std::find(s.begin(), s.end(), key);
    if (it != s.end()) {
        std::cout << "Found via generic find (Linear)\n";
    }
}
